import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"安装 A1111（SD WebUI）","description":"安装 AUTOMATIC1111 Stable Diffusion WebUI，开启 --api 与局域网，供 MiniTavern 生图连接。","frontmatter":{"title":"安装 A1111（SD WebUI）","description":"安装 AUTOMATIC1111 Stable Diffusion WebUI，开启 --api 与局域网，供 MiniTavern 生图连接。","head":[["meta",{"property":"og:title","content":"安装 A1111（SD WebUI） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安装 AUTOMATIC1111 Stable Diffusion WebUI，开启 --api 与局域网，供 MiniTavern 生图连接。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local/image-gen/a1111"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local/image-gen/a1111"}]]},"headers":[],"relativePath":"local/image-gen/a1111.md","filePath":"local/image-gen/a1111.md","lastUpdated":1786517442000}'),n={name:"local/image-gen/a1111.md"};function l(h,a,p,o,d,r){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="安装-a1111-sd-webui" tabindex="-1">安装 A1111（SD WebUI） <a class="header-anchor" href="#安装-a1111-sd-webui" aria-label="Permalink to &quot;安装 A1111（SD WebUI）&quot;">​</a></h1><p>AUTOMATIC1111（常称 <strong>A1111 / SD WebUI</strong>）提供浏览器界面与 REST API（<code>/sdapi/v1/txt2img</code>）。<br> MiniTavern 的 <strong>A1111(SD WebUI)</strong> 平台即对接此 API；<strong>SD.Next</strong> 等同协议亦可尝试。</p><p>官方仓库：<a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui" target="_blank" rel="noreferrer">AUTOMATIC1111/stable-diffusion-webui</a></p><h2 id="硬件建议" tabindex="-1">硬件建议 <a class="header-anchor" href="#硬件建议" aria-label="Permalink to &quot;硬件建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>显存</th><th>建议</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5、较小分辨率</td></tr><tr><td>8GB+</td><td>SDXL 更稳妥</td></tr><tr><td>仅 CPU</td><td>可跑但极慢，仅作验证</td></tr></tbody></table><h2 id="windows-推荐入门" tabindex="-1">Windows（推荐入门） <a class="header-anchor" href="#windows-推荐入门" aria-label="Permalink to &quot;Windows（推荐入门）&quot;">​</a></h2><h3 id="_1-安装依赖" tabindex="-1">1. 安装依赖 <a class="header-anchor" href="#_1-安装依赖" aria-label="Permalink to &quot;1. 安装依赖&quot;">​</a></h3><ol><li>安装 <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a>。</li><li>安装 <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.10.x</a>（安装时勾选 <strong>Add python.exe to PATH</strong>）。</li><li>建议已安装较新的 <strong>NVIDIA 驱动</strong>（有 NVIDIA 显卡时）。</li></ol><h3 id="_2-下载-webui" tabindex="-1">2. 下载 WebUI <a class="header-anchor" href="#_2-下载-webui" aria-label="Permalink to &quot;2. 下载 WebUI&quot;">​</a></h3><p>在合适目录（如 <code>D:\\AI</code>）打开 PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTOMATIC1111</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui</span></span></code></pre></div><h3 id="_3-首次启动" tabindex="-1">3. 首次启动 <a class="header-anchor" href="#_3-首次启动" aria-label="Permalink to &quot;3. 首次启动&quot;">​</a></h3><p>双击或在终端运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">webui-user.bat</span></span></code></pre></div><p>首次会自动下载依赖与基础组件，耗时较长。完成后浏览器一般打开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860</span></span></code></pre></div><h3 id="_4-开启-api-局域网-连手机必做" tabindex="-1">4. 开启 API + 局域网（连手机必做） <a class="header-anchor" href="#_4-开启-api-局域网-连手机必做" aria-label="Permalink to &quot;4. 开启 API + 局域网（连手机必做）&quot;">​</a></h3><p>编辑同目录下的 <code>webui-user.bat</code>，找到 <code>COMMANDLINE_ARGS</code> 一行，改为例如：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--api --listen</span></span></code></pre></div><p>说明：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--api</code></td><td>开启 <code>/sdapi/v1/*</code>（<strong>MiniTavern 必需</strong>）</td></tr><tr><td><code>--listen</code></td><td>监听 <code>0.0.0.0</code>，允许局域网设备访问</td></tr><tr><td><code>--port 7860</code></td><td>可选；改端口时 App 里同步改</td></tr></tbody></table><p>保存后重新运行 <code>webui-user.bat</code>。</p><p>可选：<code>--api-auth 用户名:密码</code> 给 API 加鉴权；若启用，在 App 生图连接的 API Key / 鉴权字段按实现要求填写（以当前 App 文案为准）。</p><h3 id="_5-验证-api" tabindex="-1">5. 验证 API <a class="header-anchor" href="#_5-验证-api" aria-label="Permalink to &quot;5. 验证 API&quot;">​</a></h3><p>本机浏览器打开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860/docs</span></span></code></pre></div><p>能看到 Swagger 文档即 API 已开。局域网验证（把 IP 换成电脑 IP）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:7860/docs</span></span></code></pre></div><h2 id="macos-linux-摘要" tabindex="-1">macOS / Linux 摘要 <a class="header-anchor" href="#macos-linux-摘要" aria-label="Permalink to &quot;macOS / Linux 摘要&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AUTOMATIC1111/stable-diffusion-webui.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable-diffusion-webui</span></span></code></pre></div><p>编辑 <code>webui-user.sh</code>，设置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--api --listen&quot;</span></span></code></pre></div><p>再执行 <code>./webui.sh</code>。Apple Silicon 可用，速度通常慢于同级 NVIDIA。</p><h2 id="下载模型-checkpoint" tabindex="-1">下载模型（Checkpoint） <a class="header-anchor" href="#下载模型-checkpoint" aria-label="Permalink to &quot;下载模型（Checkpoint）&quot;">​</a></h2><ol><li>从 <a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> 或 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> 下载 <code>.safetensors</code> 模型。</li><li>放入：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stable-diffusion-webui/models/Stable-diffusion/</span></span></code></pre></div><ol start="3"><li>在 WebUI 左上角刷新并选择模型；或重启 WebUI。</li></ol><p>入门可先下一款 SD 1.5 或 SDXL 通用模型，确认能在 WebUI 里手动出图，再连 App。</p><h2 id="防火墙" tabindex="-1">防火墙 <a class="header-anchor" href="#防火墙" aria-label="Permalink to &quot;防火墙&quot;">​</a></h2><p>Windows：首次监听时允许专用网络访问，或在防火墙中放行端口 <strong>7860</strong>。<br> 手机必须与电脑同一局域网；访客 Wi‑Fi 常隔离客户端。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./connect-app">在 MiniTavern 中配置</a>（平台选 A1111，Base URL 填电脑局域网地址）</li><li>对照：<a href="./index">生图模型部署</a> · App 内 <a href="/ultra_guides/manual/model-link">模型连接 · 生图</a></li></ul>`,42)])])}const b=i(n,[["render",l]]);export{k as __pageData,b as default};
